class MediaDatabase:
    """
    用于管理和查询演员及其作品信息的数据库类
    """
    def __init__(self):
        self._data = {}

    def add_record(self, performer_name: str, works: list):
        """
        添加或更新演员及其作品列表
        """
        if performer_name in self._data:
            self._data[performer_name].extend(works)
            # 去重
            self._data[performer_name] = list(set(self._data[performer_name]))
        else:
            self._data[performer_name] = works

    def get_works(self, performer_name: str) -> list:
        """
        获取特定演员的作品列表
        """
        return self._data.get(performer_name, [])

    def search_by_work(self, work_title: str) -> list:
        """
        根据作品名称查询参与的演员
        """
        performers = []
        for performer, works in self._data.items():
            if work_title in works:
                performers.append(performer)
        return performers

# 实例化与使用示例
